function getReceipt() {
    // This initializes our string so it can get passed from
    // function to function, growing line by line into a full receipt
    var text1 = "<h3>You Ordered:</h3>";
    var runningTotal = 0;
    var sizeTotal = 0;
    var sizeArray = document.getElementsByClassName("size");
    for (var i = 0; i < sizeArray.length; i++) {
        if (sizeArray[i].checked) {
            var selectedSize = sizeArray[i].value;
            text1 = text1 + selectedSize + "<br>";
        }
    }
    if (selectedSize === "Personal Pizza") {
        sizeTotal = 6;
    } else if (selectedSize === "Small Pizza") {
        sizeTotal = 8;
    } else if (selectedSize === "Medium Pizza") {
        sizeTotal = 10;
    } else if (selectedSize === "Large Pizza") {
        sizeTotal = 14;
    } else if (selectedSize === "Extra Large Pizza") {
        sizeTotal = 16;
    }
    runningTotal = sizeTotal;
    console.log(selectedSize + " = $" + sizeTotal + ".00");
    console.log("size text1: " + text1);
    console.log("subtotal: $" + runningTotal + ".00");
    //these variables will get passed on to each function
    getTopping(runningTotal, text1);
};


function getTopping(runningTotal, text1) {

    var toppingTotal = 0;
    var selectedTopping = [];
    var toppingArray = document.getElementsByClassName("toppings");
    text1 += "<ul>";
    for (var j = 0; j < toppingArray.length; j++) {
        if (toppingArray[j].checked) {
            selectedTopping.push(toppingArray[j].value);
            console.log("selected topping item: (" + toppingArray[j].value + ")");
            text1 = `<li> ${text1}  ${toppingArray[j].value} </li>`;
        }
    }
    text1 += "</ul>";

    var toppingCount = selectedTopping.length;
    if (toppingCount > 1) {
        toppingTotal = (toppingCount - 1);
    } else {
        toppingTotal = 0;
    }

    runningTotal = (runningTotal + toppingTotal);
    console.log("total selected topping items: " + toppingCount);
    console.log(toppingCount + " topping - 1 free topping = " + "$" + toppingTotal + ".00");
    console.log("topping text1: " + text1);
    console.log("Purchase Total: " + "$" + runningTotal + ".00");
    document.getElementById("showText").innerHTML = text1;
    document.getElementById("totalPrice").innerHTML = "<h3>Total: <strong>$" +
        runningTotal + ".00" + "</strong></h3>";
};

try {
    document.getElementById("page-title").innerText = document.title;
} catch {

}
document.title =  document.title + " | " + window.location.hostname;

:root {


    --bg-deep-navy: #0b1021;
    --bg-panel-dark: #152036;
    --bg-panel-light: #23314d;
    --body-bg: var(--bg-deep-navy);
    --accent-gold: #df9f43;
    --text-main: #e2e8f0;
    --text-bright: #ffffff;
    --text-gray: #7E878E;
    --body-text: var(--text-main);
    --border-color: #314163;
    --video-overlay: rgba(11, 16, 33, 0.7);
    --accent-glow: rgba(223, 159, 67, 0.5);
    --text-muted: #b8c4d8;
    --border-input: #41506b;
    --bg-input: #101a2d;
    --text-placeholder: #9baac0;
    --border-input-hover: #71809c;
    --shadow-focus: rgba(223, 159, 67, 0.12);
    --accent-gold-hover: #efb55d;
    --shadow-button-hover: rgba(223, 159, 67, 0.18);

    --font-fam-bold: "Isometra", 'Courier New', Courier, monospace;
    --font-fam-default: "JetBrains Mono", "Edu QLD Hand", 'Courier New', Courier, monospace;
    --font-fam-decore: "Edu QLD Hand", 'Courier New', Courier, monospace;
}

@import url('https://fonts.googleapis.com/css2?family=Isometra&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Edu+QLD+Hand:wght@400..700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:ital,wght@0,100..800;1,100..800&display=swap');
@import 'color.css';
/* ###################################################
                    BASE SETUP
 ################################################### */

*,
*::before,
*::after {
    margin: 0;
    padding-top: 0;
    box-sizing: border-box;
}


html {
    overflow-x: hidden;
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-fam-default);
    font-size: 24px;

    margin: 0;
    padding: 0;
    color: var(--body-text);
    display: flex;
    flex-direction: column;
    min-height: 100vh;


background-color: var(--body-bg); 

    background-image: linear-gradient(rgba(11, 16, 33, 0.8), rgba(11, 16, 33, 0.8)), url('../images/pizza_party.jpg');
    background-size: cover; 
    background-attachment: fixed; 
    background-position: center; 
    background-repeat: no-repeat;

}

/* ###################################################  */


.h1 {
    font-family: var(--font-fam-default);
     /* "Isometra", 'Courier New', Courier, monospace; */
    color: var(--text-main);
}

.h3 {
    font-family: var(--font-fam-decore);
    color: var(--text-main);
}

.div {
    font-family: var(--font-fam-decore);
    color: var(--text-main);
}

li {
   list-style-type: none;
}

.menu-title {
    margin:0 0px 0 20px;
}

#menuBG {
    width: auto;
    height: 470px;
    margin: 10px auto;
    padding-bottom:  20px;
}

#frmMenu {
   width: 100%;
    display: flex;
    flex-wrap: wrap; 
    justify-content: space-between;
}


.menu {
    flex: 1; /* 1 space */
    min-width: 200px; 
    margin: 0 10px;
}



.ingreadiant:hover{
    
background-color: rgba(95, 158, 160, 0.404);

}

#totalPrice {
    width: 200px;
    height: 190px;
    margin: 0 auto;
    float: right;
}
.left, .right {
    float: none;
    width: auto;
}

#showText {
    width: 200px;
    height: 190px;
    margin: 0px auto;
    float: left;
}

#cart {
    width: 100%; 
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid var(--border-color); 
}

#btnOrder {
    margin: 10px 0px 0px 100px;
    width: 100px;
    height: 40px;
}
